*/


CheckDateArrVar[8] = "packStatSubmitDd"; // 일괄신고서제출일자      	
CheckDateArrVar[9] = "packStatEfctOccrDd"; // 일괄신고서효력발생일자   	
CheckDateArrVar[10] = "packStatIsuStrtDd"; // 일괄신고서발행개시일자   	
CheckDateArrVar[11] = "packStatIsuEndDd"; // 일괄신고서발행종료일자   	

CheckDateArrVar[12] = "listApplSchdlDd"; // 상장신청일            	

// ELW일괄신고서 데이타 검증 
/**
 * @method
 * @name fn_issSchdCheckValues
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_issSchdCheckValues = function() {
    // 10083(시티증권은 필수입력항목에서 제외
    for (var idx = 0; idx < 13; idx++) {
        if (idx == 0) {
            /****************************
            if ( form["isuYymm"][idx].value == 0 ) {
                alert("발행년월을 입력해 주십시오.");
                form["isuYymm"][idx].focus();
                return false;
            }
            if ( form["isuSchdlAmt"][idx].value == 0 ) {
                alert("발행계획을 입력해 주십시오.");
                form["isuSchdlAmt"][idx].focus();
                return false;
            }
            *****************************/

            /*
	            if ( form["isuPrfmAmt"][idx].value == 0 ) {
	                alert("발행실적을 입력해 주십시오.");
	                form["isuPrfmAmt"][idx].focus();
	                return false;
	            }
	            */
        } else {
            if (form["isuYymm"][idx].getValue() > 0) {
                if (idx == 12) {
                    if (form["isuSchdlAmt"][idx].getValue() > 0) {
                        /*
	                            if (form["isuPrfmAmt"][idx].value == 0) {
	                                alert("발행실적을 입력해 주십시오.");
	                                form["isuPrfmAmt"][idx].focus();
	                                return false;
	                            }
	                            */
                    }
                } else {
                    /****************************
                    if (form["isuSchdlAmt"][idx].value == 0) {
                        alert("발행계획을 입력해 주십시오.");
                        form["isuSchdlAmt"][idx].focus();
                        return false;
                    }
		            *****************************/
                    /*
	                    if (form["isuPrfmAmt"][idx].value == 0) {
	                        alert("발행실적을 입력해 주십시오.");
	                        form["isuPrfmAmt"][idx].focus();
	                        return false;
	                    }
	                    */
                }
            }
        }
    }
    return true;
};
/**
 * @method
 * @name fn_CommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CommaValueAll = function() {
    fn_ObjValueSetComma(form["isuPrc"]); //   발행가격                         
    fn_ObjValueSetComma(form["isuShrs"]); //   발행증권수                       
    fn_ObjValueSetComma(form["isuTotSum"]); //   발행총액                       
    fn_ObjValueSetComma(form["elwConvRto"]); //   ELW전환비율                      
    fn_ObjValueSetComma(form["elwUlyBasPrc"]); //   ELW기초자산기초가격              
    fn_ObjValueSetComma(form["elwExerPrc"]); //   ELW행사가격                      
    fn_ObjValueSetComma(form["elwPrcUpPartcRt"]); //   ELW가격상승참가율                
    fn_ObjValueSetComma(form["elwCompnsRt"]); //   ELW보상률                        
    fn_ObjValueSetComma(form["elwFinalPayVal"]); //   ELW확정지급액                    
    fn_ObjValueSetComma(form["riskfreIntRt"]); //   무위험이자율                     
    fn_ObjValueSetComma(form["elwDivRt"]); //   ELW배당률                        
    fn_ObjValueSetComma(form["applVoltRto"]); //   적용변동성비율                   
    fn_ObjValueSetComma(form["ordSpdRto"]); //   호가스프레드                     
    fn_ObjValueSetComma(form["elwKoBasPrc"]); //   조기종료발생기준가격/지수
    fn_ObjValueSetComma(form["isuExp"]); //제반비용      

    for (var i = 0; i < form["isuSchdlAmt"].length; i++) {
        fn_ObjValueSetComma(form["isuSchdlAmt"][i]);
        fn_ObjValueSetComma(form["isuPrfmAmt"][i]);
    }
};
/**
 * @method
 * @name fn_RmCommaValueAll
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmCommaValueAll = function() {
    fn_ObjValueResetRmComma(form["isuPrc"]); //   발행가격                         
    fn_ObjValueResetRmComma(form["isuShrs"]); //   발행증권수                       
    fn_ObjValueResetRmComma(form["elwConvRto"]); //   ELW전환비율                      
    fn_ObjValueResetRmComma(form["elwUlyBasPrc"]); //   ELW기초자산기초가격              
    fn_ObjValueResetRmComma(form["elwExerPrc"]); //   ELW행사가격                      
    fn_ObjValueResetRmComma(form["elwPrcUpPartcRt"]); //   ELW가격상승참가율                
    fn_ObjValueResetRmComma(form["elwCompnsRt"]); //   ELW보상률                        
    fn_ObjValueResetRmComma(form["elwFinalPayVal"]); //   ELW확정지급액                    
    fn_ObjValueResetRmComma(form["riskfreIntRt"]); //   무위험이자율                     
    fn_ObjValueResetRmComma(form["elwDivRt"]); //   ELW배당률                        
    fn_ObjValueResetRmComma(form["applVoltRto"]); //   적용변동성비율                   
    fn_ObjValueResetRmComma(form["ordSpdRto"]); //   호가스프레드          

    //fn_ObjValueResetRmComma(form["elwKoBasPrc"    ]); //   조기종료발생기준가격/지수
    //fn_ObjValueResetRmComma(form["isuExp"      ]);	  //   제반비용


    if (form["isuSchdlAmt"].length) {
        for (var i = 0; i < form["isuSchdlAmt"].length; i++) {
            fn_ObjValueResetRmComma(form["isuSchdlAmt"][i]);
            fn_ObjValueResetRmComma(form["isuPrfmAmt"][i]);
        }
    } else {
        fn_ObjValueResetRmComma(form["isuSchdlAmt"]);
        fn_ObjValueResetRmComma(form["isuPrfmAmt"]);
    }
};




//컴마 제거시, null인 항목에 대해 0으로 변환되지 않도록 수정
/**
 * @method
 * @name fn_RmCommaValueAllForKO
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RmCommaValueAllForKO = function() {
    scwin.fn_ObjValueResetRmCommaForKO(form["elwKoBasPrc"]); //   조기종료발생기준가격/지수
    scwin.fn_ObjValueResetRmCommaForKO(form["isuExp"]); //   제반비용

};
/**
 * @method
 * @name fn_ObjValueResetRmCommaForKO
 * @description desc
 * @param {string} numObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ObjValueResetRmCommaForKO = function(numObj) {
    if (numObj != null && numObj.getValue().length > 0) {
        numObj.setValue(fn_RmComma(numObj.getValue()));
    }
};
